/** Contract spec entry kinds mirrored from the on-chain contract spec. */
export const enum ContractEntryKind {
  Function = "function",
  Event = "event",
}

/** A single argument of a contract function. */
export interface ContractFunctionArg {
  readonly name: string;
  readonly type: string;
}

/** A contract function exposed by the incentive-pool. */
export interface ContractFunctionSpec {
  readonly kind: ContractEntryKind.Function;
  readonly name: string;
  readonly doc: string;
  readonly args: readonly ContractFunctionArg[];
  readonly returns: string;
}

/** A contract event emitted by the incentive-pool. */
export interface ContractEventSpec {
  readonly kind: ContractEntryKind.Event;
  readonly name: string;
  readonly doc: string;
  readonly topics: readonly string[];
  readonly data: readonly ContractFunctionArg[];
}

export type ContractSpecEntry = ContractFunctionSpec | ContractEventSpec;

